import discordfrom discord import Colorfrom discord.ext import commandsfrom utils.EmbedGeneratorUtil import EmbedGeneratorfrom utils.custom.errors.FingerBangThePoonTangBotError import EmptyWordOrWordsStringErrorfrom print_color import printclass DMCommand(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot    @commands.guild_only()    @commands.command(name="dm", help="Takes The Message The User Types, And Direct Messages (DM) It To The User!")    async def dm(self, ctx: discord.ext.commands.Context, *, msg: str = commands.Parameter(name="msg", description="The Message You Would Like To Send Yourself In A DM!", kind=commands.Parameter.POSITIONAL_OR_KEYWORD)):        """        Takes the message the user types, and Direct Messages (DM) it to the user!        :param ctx: This is the discord Interaction we can access data from.        :param msg: The message you would like to send yourself in a DM.        :return:        """        if msg is None:            raise EmptyWordOrWordsStringError(error="The Message Cannot Be None! Must Input A Valid Message To Send Yourself!")        try:            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="What You Chose To DM Yourself, Is Below!", description=msg, colour=Color.dark_blue(), timestamp=True)            await ctx.author.send(embed=embed)        except Exception as e:            print(e, tag="FAILURE", tag_color="red", color="red")            self.logger.info("[FAILURE] There Has Been A Failure At Line 27-33 in DMCommand.py")            raise UnknownCommandFailure(error=e)async def setup(bot: commands.Bot):    await bot.add_cog(DMCommand(bot))